create table if not exists public.story_views (id bigint generated by default as identity primary key, story_id bigint not null references public.stories(id) on delete cascade, user_id bigint not null references public.users(id) on delete cascade, viewed_at timestamptz not null default now(), unique(story_id,user_id));
create table if not exists public.story_reactions (id bigint generated by default as identity primary key, story_id bigint not null references public.stories(id) on delete cascade, user_id bigint not null references public.users(id) on delete cascade, reaction text not null, created_at timestamptz not null default now(), unique(story_id,user_id));
create table if not exists public.story_replies (id bigint generated by default as identity primary key, story_id bigint not null references public.stories(id) on delete cascade, user_id bigint not null references public.users(id) on delete cascade, message_id bigint references public.messages(id) on delete set null, body text not null, created_at timestamptz not null default now());